/**
 * Copies the TextMate grammar generated by @elastic/textmate-esql into
 * syntaxes/, where the manifest's `contributes.grammars` path points. The
 * grammar's source of truth is that package; syntaxes/ here is gitignored.
 */

import { copyFileSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const PACKAGE_ROOT = join(__dirname, '..');
// Resolved by path: the package's `exports` map does not expose syntaxes/,
// and pnpm always links a declared dependency into this package's node_modules.
const SOURCE = join(
  PACKAGE_ROOT,
  'node_modules',
  '@elastic',
  'textmate-esql',
  'syntaxes',
  'esql.tmLanguage.json'
);
const OUT_DIR = join(PACKAGE_ROOT, 'syntaxes');

mkdirSync(OUT_DIR, { recursive: true });
copyFileSync(SOURCE, join(OUT_DIR, 'esql.tmLanguage.json'));
console.log(`Copied ${SOURCE} -> ${OUT_DIR}`);
